  HB = `Якщо встановлено значення true, організатори події повинні вказати, хто проводить подію. Це показується на сторінці розпродажу для покупців, щоби вони розуміли, хто є організатором, і не думали, що подію проводить Valve.`,
  UB = `Видалити всіх вказаних організаторів події`,
  WB = `Слід ввести опис організатора цього розпродажу.`,
  GB = `%1$s рекомендує`,
  KB = `Рекомендовано кураторами, яких ви відстежуєте`,
  qB = `Розробник: %1$s`,
  JB = `Видавець: %1$s`,
  YB = `Серія ігор: %1$s`,
  XB = `Рекомендовано, тому що ви грали в ігри з позначками: %1$s`,
  ZB = `Рекомендовано, тому що ви використовували ПЗ з позначками: %1$s`,
  QB = `Рекомендовано, тому що ви дивилися відео з позначками: %1$s`,
