  lpe = `Якщо ви надасте дозвіл на збір даних про частоту кадрів, вони зберігатимуться анонімно й не будуть пов’язані з вашим акаунтом Steam. Ці дані ідентифікуються за типом обладнання, на якому ви граєте. Вони допомагають нам дізнатися про сумісність ігор і поліпшувати досвід користування пристроями, на яких інстальовано Steam.`,
  upe = `Якщо бажатимете змінити цей дозвіл пізніше, можете знайти його в налаштуваннях акаунта Steam на вкладці «Дані та перегляд сторінок».`,
  dpe = `Докладніше`,
  fpe = `Сумісність зі Steam Deck`,
  ppe = `Steam Deck Verified — відгуки користувачів`,
  mpe = `Немає даних`,
  hpe = `%1$s респондентів погоджуються з оцінкою «%2$s» цієї гри.`,
  gpe = `Для довідки: середній показник погодження з усіма оцінками програми Deck Verified — %1$s.`,
  _pe = `%1$s%`,
  vpe = `Хоч користувачі загалом погоджуються з присвоєною іграм оцінкою «Сумісна» (>%1$s%), це допоможе краще зрозуміти досвід гравців, які не погодилися з нею, особливо в контексті конкретної гри або оновлення.`,
  ype = `Швидкодія`,
  bpe = `Читабельність`,
  xpe = `Стабільність`,
  Spe = `Введення`,
  Cpe = `Інше`,
  wpe = `Це дані на основі звітів (%1$s) за останні %2$s дн. від користувачів, які погодилися надавати відгук на Steam Deck.`,
  Tpe = `Користувачі, які %1$s зі статусом гри «%2$s», вказали такі причини для цього.`,
  Epe = `не погодилися`,
  Dpe = `Дані про частоту кадрів на Steam Deck`,
  Ope = `Середня частота кадрів на Steam Deck`,
  kpe = `Середня частота кадрів %1$s на %2$s: %3$s`,
  Ape = `Середня частота кадрів у цій грі на %1$s: %2$s`,
  jpe = `%1$s кадрів/с`,
  Mpe = `Дані про частоту кадрів на Steam Deck базуються на звітах про частоту кадрів за %1$s дн. від користувачів Steam Deck, які погодилися надавати ці дані.`,
  Npe = `Дані про частоту кадрів на Steam Deck базуються на звітах про частоту кадрів від користувачів Steam Deck, які погодилися надавати ці дані.`,
  Ppe = `Примітка: дисперсія наразі не доступна, але ми плануємо її додати в бета-версії. Завдяки цій інформації ви зможете побачити, є частота кадрів стабільною чи сильно варіюється.`,
  Fpe = `Причина`,
  Ipe = `Кількість відповідей`,
  Lpe = `Джерелом даних для гістограми є звіти про частоту кадрів для %1$s від користувачів %2$s, які погодилися їх надавати.`,
  Rpe = `Джерелом даних для гістограми є звіти про частоту кадрів для цієї гри від користувачів %1$s, які погодилися їх надавати.`,
  zpe = `Розподіл частоти кадрів`,
  Bpe = `Частота кадрів`,
  Vpe = `% вибірок`,
  Hpe = `Графік з’явиться, коли буде зібрано достатньо даних`,
  Upe = `Включити всі дані`,
  Wpe = `Стандартно дані відфільтровуються, якщо на пристрої не встановлено стандартне обмеження частоти кадрів.`,
  Gpe = `Steam Deck LCD`,
  Kpe = `Steam Deck OLED`,
  qpe = `Модель Steam Deck`,
  Jpe = `Розподіл частоти кадрів`,
  Ype = `Steam усе ще збирає дані про частоту кадрів для %1$s на %2$s`,
  Xpe = `Steam усе ще збирає дані про частоту кадрів для цієї гри на %1$s`,
  Zpe = `Steam усе ще збирає дані про частоту кадрів для цієї гри`,
  Qpe = `На цьому графіку показано вибірку даних про частоту кадрів, отриманих від користувачів, які погодилися на анонімний збір цих даних під час гри в %1$s на %2$s. Кожен стовпець показує відсоток вибірок із відповідною частотою кадрів.`,
  $pe = `На цьому графіку показано вибірку даних про частоту кадрів, отриманих від користувачів, які погодилися на анонімний збір цих даних під час гри в цю гру на %1$s. Кожен стовпець показує відсоток вибірок із відповідною частотою кадрів.`,
  eme = `Докладніше`,
  tme = `Включені лише дані, зібрані за стандартного обмеження кадрів %1$s, що становить %2$s к/с. Час бездіяльності та недійсні вибірки не враховуються. З кожного ігрового сеансу збирається кілька вибірок.`,
  nme = `Прогалини на графіку (наприклад, між %1$s і %2$s к/с) можуть бути спричинені вертикальною синхронізацією, що синхронізує доставку кадрів із частотою оновлення екрана для уникнення розривів зображення. Як наслідок, вибірки можуть бути зосереджені в області %1$s і %2$s к/с, навіть якщо значення середньої частоти кадрів гри знаходиться посередині. Така поведінка вертикальної синхронізації є очікуваною, і хоча вона може впливати на темп кадрів, це не означає, що вона спричиняє помітні підвисання.`,
  rme = `БЕТА`,
  ime = `Предмет майстерні для %1$s`,
  ame = `Знімок екрана %1$s`,
  ome = `Відео %1$s`,
  sme = `Ілюстрація від спільноти для %1$s`,
  cme = `Гра з Greenlight`,
