  hme = `Вставлене тут посилання було вилучено нашими фільтрами. Зазвичай це робиться для запобігання фішінгу і атакам зловмисним ПЗ.`,
  gme = `{ПОСИЛАННЯ НА ЗАБЛОКОВАНИЙ ВМІСТ ВИЛУЧЕНО}`,
